 32→/// Load environment variables from system.
 33→pub fn load_system_env() -> HashMap<String, String> {
 34→    std::env::vars().collect()
 35→}
 36→
 37→/// Load environment variables from a dotenv-style file.
 38→///
 39→/// # Format
 40→///
 41→/// ```text
 42→/// # Comment
 43→/// KEY=value
 44→/// QUOTED="value with spaces"
 45→/// SINGLE='also works'
 46→/// ```
 47→///
 48→/// # Errors
 49→///
 50→/// Returns `ConfigNotFound` if the file doesn't exist.
 51→/// Returns `ConfigParseError` for invalid lines.
 52→pub fn load_env_file(path: &Path) -> Result<HashMap<String, String>> {
 53→    let content = fs::read_to_string(path).map_err(|e| {
 54→        if e.kind() == std::io::ErrorKind::NotFound {
 55→            BivvyError::ConfigNotFound {
 56→                path: path.to_path_buf(),
 57→            }
 58→        } else {
 59→            BivvyError::Io(e)
 60→        }
 61→    })?;
 62→
 63→    parse_dotenv(&content, path)
 64→}
 65→
 66→/// Load env file if it exists, return empty map otherwise.
 67→pub fn load_env_file_optional(path: &Path) -> HashMap<String, String> {
 68→    load_env_file(path).unwrap_or_default()
 69→}
 70→
 71→/// Parse dotenv-style content.
 72→fn parse_dotenv(content: &str, source_path: &Path) -> Result<HashMap<String, String>> {
 73→    let mut env = HashMap::new();
 74→
 75→    for (line_num, line) in content.lines().enumerate() {
 76→        let line = line.trim();
 77→
 78→        // Skip empty lines and comments
 79→        if line.is_empty() || line.starts_with('#') {
 80→            continue;
 81→        }
 82→
 83→        // Parse KEY=value
 84→        if let Some(eq_pos) = line.find('=') {
 85→            let key = line[..eq_pos].trim().to_string();
 86→            let mut value = line[eq_pos + 1..].trim().to_string();
 87→
 88→            // Remove surrounding quotes if present
 89→            if ((value.starts_with('"') && value.ends_with('"'))
 90→                || (value.starts_with('\'') && value.ends_with('\'')))
 91→                && value.len() >= 2
 92→            {
 93→                value = value[1..value.len() - 1].to_string();
 94→            }
 95→
 96→            env.insert(key, value);
 97→        } else {
 98→            return Err(BivvyError::ConfigParseError {
 99→                path: source_path.to_path_buf(),
100→                message: format!("Invalid line {}: {}", line_num + 1, line),

 1→//! Bivvy CLI entry point.
 2→
 3→use std::process::ExitCode;
 4→
 5→use bivvy::cli::{Cli, CommandDispatcher, Commands};
 6→use bivvy::shell::is_ci;
 7→use bivvy::ui::{create_ui, OutputMode};
 8→use clap::Parser;
 9→use tracing_subscriber::{fmt, prelude::*, EnvFilter};
10→
11→/// Initialize the tracing subscriber for logging.
12→///
13→/// Log level is controlled by:
14→/// 1. `--debug` flag sets level to DEBUG
15→/// 2. `RUST_LOG` environment variable (if set)
16→/// 3. Default is INFO
17→fn init_tracing(debug: bool) {
18→    let filter = if debug {
19→        EnvFilter::new("bivvy=debug")
20→    } else {
21→        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
22→    };
23→
24→    tracing_subscriber::registry()
25→        .with(fmt::layer().with_target(false))
26→        .with(filter)
27→        .init();
28→}
29→
30→fn main() -> ExitCode {
31→    let cli = Cli::parse();
32→    init_tracing(cli.debug);
33→
34→    tracing::debug!("Bivvy starting with args: {:?}", cli);
35→
36→    // Determine output mode
37→    let output_mode = if cli.quiet {
38→        OutputMode::Quiet
39→    } else if cli.verbose {
40→        OutputMode::Verbose
41→    } else {
42→        OutputMode::Normal
43→    };
44→
45→    // Handle --no-color
46→    if cli.no_color {
47→        std::env::set_var("NO_COLOR", "1");
48→    }
49→
50→    // Determine project root
51→    let project_root = cli
52→        .project
53→        .as_ref()
54→        .cloned()
55→        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
56→
57→    // Check if non-interactive (CI mode or explicit flag)
58→    let is_interactive = match &cli.command {
59→        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
60→        _ => !is_ci(),
61→    };
62→
63→    // Create UI
64→    let mut ui = create_ui(is_interactive, output_mode);
65→
66→    // Dispatch command
67→    let dispatcher = CommandDispatcher::new(project_root);
68→
69→    match dispatcher.dispatch(&cli, ui.as_mut()) {
70→        Ok(result) => ExitCode::from(result.exit_code as u8),
71→        Err(e) => {
72→            ui.error(&format!("Error: {}", e));
73→            ExitCode::from(1)
74→        }
75→    }
76→}
