//! Configuration validation rules.
//!
//! This module validates configuration for correctness:
//! - Steps must have either template or command
//! - depends_on must reference existing steps
//! - Workflows must reference existing steps
//! - No circular dependencies allowed

use crate::config::schema::BivvyConfig;
use crate::error::{BivvyError, Result};
use std::collections::HashSet;

/// Validation error with context.
#[derive(Debug, Clone)]
pub struct ValidationError {
    /// Rule identifier
    pub rule: String,
    /// Human-readable error message
    pub message: String,
    /// Step name if error is step-specific
    pub step: Option<String>,
    /// Workflow name if error is workflow-specific
    pub workflow: Option<String>,
}

/// Validate a configuration and return all errors.
///
/// This function collects all validation errors rather than stopping
/// at the first one, allowing users to fix multiple issues at once.
pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
    let mut errors = Vec::new();

    errors.extend(validate_steps(config));
    errors.extend(validate_workflows(config));
    errors.extend(validate_dependencies(config));

    errors
}

/// Validate step definitions.
fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
    let mut errors = Vec::new();

    for (name, step) in &config.steps {
        // Step must have either template or command
        if step.template.is_none() && step.command.is_none() {
            errors.push(ValidationError {
                rule: "missing-command".to_string(),
                message: format!("Step '{}' must have either 'template' or 'command'", name),
                step: Some(name.clone()),
                workflow: None,
            });
        }

        // Validate depends_on references
        for dep in &step.depends_on {
            if !config.steps.contains_key(dep) {
                errors.push(ValidationError {
                    rule: "unknown-step".to_string(),
                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
                    step: Some(name.clone()),
                    workflow: None,
                });
            }
        }
    }

    errors
}

/// Validate workflow definitions.
fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
    let mut errors = Vec::new();

    for (name, workflow) in &config.workflows {
        // Validate step references
        for step_name in &workflow.steps {
            if !config.steps.contains_key(step_name) {
                errors.push(ValidationError {
                    rule: "unknown-workflow-step".to_string(),
                    message: format!(
                        "Workflow '{}' references step '{}' which does not exist",
                        name, step_name
                    ),
                    step: None,
                    workflow: Some(name.clone()),
                });
            }
        }

        // Validate override references
        for step_name in workflow.overrides.keys() {
            if !workflow.steps.contains(step_name) {
                errors.push(ValidationError {
                    rule: "unknown-override-step".to_string(),
                    message: format!(
                        "Workflow '{}' has override for '{}' which is not in the workflow",
                        name, step_name
                    ),
                    step: None,
                    workflow: Some(name.clone()),
                });
            }
        }
    }

    errors
}

/// Validate step dependencies for cycles.
fn validate_dependencies(config: &BivvyConfig) -> Vec<ValidationError> {
    let mut errors = Vec::new();
    let mut visited = HashSet::new();
    let mut rec_stack = HashSet::new();
    let mut path = Vec::new();

    for step_name in config.steps.keys() {
        if let Some(cycle) =
            detect_cycle(step_name, config, &mut visited, &mut rec_stack, &mut path)
        {
            errors.push(ValidationError {
                rule: "circular-dependency".to_string(),
                message: format!("Circular dependency detected: {}", cycle),
                step: Some(step_name.clone()),
                workflow: None,
            });
            break; // Only report one cycle
        }
    }

    errors
}

fn detect_cycle(
    step: &str,
    config: &BivvyConfig,
    visited: &mut HashSet<String>,
    rec_stack: &mut HashSet<String>,
    path: &mut Vec<String>,
) -> Option<String> {
    if rec_stack.contains(step) {
        // Found cycle - format it
        let cycle_start = path.iter().position(|s| s == step).unwrap();
        let cycle: Vec<_> = path[cycle_start..].to_vec();
        return Some(format!("{} -> {}", cycle.join(" -> "), step));
    }

    if visited.contains(step) {
        return None;
    }

    visited.insert(step.to_string());
    rec_stack.insert(step.to_string());
    path.push(step.to_string());

    if let Some(step_config) = config.steps.get(step) {
        for dep in &step_config.depends_on {
            if let Some(cycle) = detect_cycle(dep, config, visited, rec_stack, path) {
                return Some(cycle);
            }
        }
    }

    path.pop();
    rec_stack.remove(step);
    None
}

/// Validate and return Result (for convenience).
///
/// # Errors
///
/// Returns `ConfigValidationError` if any validation rules fail.
pub fn validate(config: &BivvyConfig) -> Result<()> {
    let errors = validate_config(config);

    if errors.is_empty() {
        Ok(())
    } else {
        let messages: Vec<_> = errors.iter().map(|e| e.message.clone()).collect();
        Err(BivvyError::ConfigValidationError {
            message: messages.join("; "),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::schema::{StepConfig, StepOverride, WorkflowConfig};

    #[test]
    fn validates_step_has_command_or_template() {
        let mut config = BivvyConfig::default();
        config
            .steps
            .insert("empty".to_string(), StepConfig::default());

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "missing-command"));
    }

    #[test]
    fn validates_depends_on_exists() {
        let mut config = BivvyConfig::default();
        let step = StepConfig {
            command: Some("echo test".to_string()),
            depends_on: vec!["nonexistent".to_string()],
            ..Default::default()
        };
        config.steps.insert("test".to_string(), step);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "unknown-step"));
    }

    #[test]
    fn validates_workflow_step_exists() {
        let mut config = BivvyConfig::default();
        let workflow = WorkflowConfig {
            steps: vec!["nonexistent".to_string()],
            ..Default::default()
        };
        config.workflows.insert("default".to_string(), workflow);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "unknown-workflow-step"));
    }

    #[test]
    fn detects_circular_dependency() {
        let mut config = BivvyConfig::default();

        let step_a = StepConfig {
            command: Some("a".to_string()),
            depends_on: vec!["b".to_string()],
            ..Default::default()
        };

        let step_b = StepConfig {
            command: Some("b".to_string()),
            depends_on: vec!["a".to_string()],
            ..Default::default()
        };

        config.steps.insert("a".to_string(), step_a);
        config.steps.insert("b".to_string(), step_b);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "circular-dependency"));
    }

    #[test]
    fn valid_config_returns_no_errors() {
        let mut config = BivvyConfig::default();

        let step_a = StepConfig {
            command: Some("a".to_string()),
            ..Default::default()
        };

        let step_b = StepConfig {
            command: Some("b".to_string()),
            depends_on: vec!["a".to_string()],
            ..Default::default()
        };

        config.steps.insert("a".to_string(), step_a);
        config.steps.insert("b".to_string(), step_b);

        let workflow = WorkflowConfig {
            steps: vec!["a".to_string(), "b".to_string()],
            ..Default::default()
        };
        config.workflows.insert("default".to_string(), workflow);

        let errors = validate_config(&config);
        assert!(errors.is_empty());
    }

    #[test]
    fn validates_workflow_override_in_workflow() {
        let mut config = BivvyConfig::default();

        let step = StepConfig {
            command: Some("test".to_string()),
            ..Default::default()
        };
        config.steps.insert("test".to_string(), step);

        let mut overrides = std::collections::HashMap::new();
        overrides.insert("other".to_string(), StepOverride::default());

        let workflow = WorkflowConfig {
            steps: vec!["test".to_string()],
            overrides,
            ..Default::default()
        };
        config.workflows.insert("default".to_string(), workflow);

        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "unknown-override-step"));
    }

    #[test]
    fn validate_returns_result() {
        let config = BivvyConfig::default();
        assert!(validate(&config).is_ok());

        let mut bad_config = BivvyConfig::default();
        bad_config
            .steps
            .insert("empty".to_string(), StepConfig::default());
        assert!(validate(&bad_config).is_err());
    }
}

//! Configuration schema definitions for Bivvy.
//!
//! This module contains all the struct definitions that map to
//! the YAML configuration file format.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Root configuration structure for bivvy.yml
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct BivvyConfig {
    /// Application name (for display purposes)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub app_name: Option<String>,

    /// Global settings
    pub settings: Settings,

    /// Remote template sources
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub template_sources: Vec<TemplateSource>,

    /// Step definitions
    #[serde(default)]
    pub steps: HashMap<String, StepConfig>,

    /// Workflow definitions
    #[serde(default)]
    pub workflows: HashMap<String, WorkflowConfig>,

    /// Secrets configuration
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub secrets: HashMap<String, SecretConfig>,

    /// Config inheritance
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extends: Option<Vec<ExtendsConfig>>,

    /// Custom requirement definitions
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub requirements: HashMap<String, CustomRequirement>,

    /// User-defined variables for interpolation.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub vars: HashMap<String, VarDefinition>,
}

/// Global settings that apply to all workflows and steps
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Settings {
    /// Default output mode: verbose, quiet, silent
    #[serde(default = "default_output")]
    pub default_output: OutputMode,

    /// Enable logging to file
    #[serde(default, skip_serializing_if = "is_false")]
    pub logging: bool,

    /// Log file path (relative to project root)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub log_path: Option<PathBuf>,

    /// Global environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Global env file to load
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,

    /// Additional secret patterns to mask
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub secret_env: Vec<String>,

    /// Enable parallel execution
    #[serde(default, skip_serializing_if = "is_false")]
    pub parallel: bool,

    /// Maximum concurrent steps
    #[serde(
        default = "default_max_parallel",
        skip_serializing_if = "is_default_max_parallel"
    )]
    pub max_parallel: usize,

    /// History retention count
    #[serde(
        default = "default_history_retention",
        skip_serializing_if = "is_default_history_retention"
    )]
    pub history_retention: usize,

    /// Default environment name (used when no --env flag and no auto-detection)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_environment: Option<String>,

    /// Named environment configurations
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub environments: HashMap<String, EnvironmentConfig>,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            default_output: default_output(),
            logging: false,
            log_path: None,
            env: HashMap::new(),
            env_file: None,
            secret_env: Vec::new(),
            parallel: false,
            max_parallel: default_max_parallel(),
            history_retention: default_history_retention(),
            default_environment: None,
            environments: HashMap::new(),
        }
    }
}

fn default_output() -> OutputMode {
    OutputMode::Verbose
}

fn default_max_parallel() -> usize {
    4
}

fn is_default_max_parallel(v: &usize) -> bool {
    *v == default_max_parallel()
}

fn default_history_retention() -> usize {
    50
}

fn is_default_history_retention(v: &usize) -> bool {
    *v == default_history_retention()
}

fn is_false(v: &bool) -> bool {
    !v
}

fn is_true(v: &bool) -> bool {
    *v
}

fn is_zero(v: &u32) -> bool {
    *v == 0
}

/// Output verbosity mode
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum OutputMode {
    #[default]
    Verbose,
    Quiet,
    Silent,
}

/// Configuration for a single setup step
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct StepConfig {
    /// Reference to a template (mutually exclusive with inline config)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub template: Option<String>,

    /// Template inputs (when using template)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub inputs: HashMap<String, serde_yaml::Value>,

    /// Step title (for display)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,

    /// Step description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Shell command to execute
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,

    /// Steps that must complete before this one
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub depends_on: Vec<String>,

    /// Check if step is already complete
    #[serde(skip_serializing_if = "Option::is_none")]
    pub completed_check: Option<CompletedCheck>,

    /// Precondition that must pass before the step runs.
    /// Unlike `completed_check` (which skips when passing), a precondition
    /// *fails* the step when it does not pass. `--force` does not bypass preconditions.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub precondition: Option<CompletedCheck>,

    /// Whether user can skip this step
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub skippable: bool,

    /// Step must run, cannot be skipped
    #[serde(default, skip_serializing_if = "is_false")]
    pub required: bool,

    /// Ask before re-running completed steps
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub prompt_if_complete: bool,

    /// Continue workflow if this step fails
    #[serde(default, skip_serializing_if = "is_false")]
    pub allow_failure: bool,

    /// Number of retries on failure
    #[serde(default, skip_serializing_if = "is_zero")]
    pub retry: u32,

    /// Step-specific environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Env file to load for this step
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,

    /// Don't fail if env_file is missing
    #[serde(default, skip_serializing_if = "is_false")]
    pub env_file_optional: bool,

    /// Required environment variables (fail if missing)
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub required_env: Vec<String>,

    /// Files to watch for change detection
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub watches: Vec<String>,

    /// Interactive prompts within this step
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub prompts: Vec<PromptConfig>,

    /// Step output settings
    #[serde(skip_serializing_if = "Option::is_none")]
    pub output: Option<StepOutputConfig>,

    /// Mark step as handling sensitive data
    #[serde(default, skip_serializing_if = "is_false")]
    pub sensitive: bool,

    /// Step requires sudo/elevated permissions
    #[serde(default, skip_serializing_if = "is_false")]
    pub requires_sudo: bool,

    /// Commands to run before the step
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub before: Vec<String>,

    /// Commands to run after the step succeeds
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub after: Vec<String>,

    /// System-level prerequisites this step requires (e.g., ruby, node, postgres-server).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub requires: Vec<String>,

    /// Per-environment overrides for this step.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub environments: HashMap<String, StepEnvironmentOverride>,

    /// Restrict this step to specific environments.
    /// Empty list (default) means "run in all environments".
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub only_environments: Vec<String>,
}

fn default_true() -> bool {
    true
}

/// Check to determine if a step has already been completed.
///
/// This enables idempotent step execution by detecting when work
/// has already been done.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum CompletedCheck {
    /// Check if a file or directory exists
    FileExists {
        /// Path to check (relative to project root)
        path: String,
    },

    /// Check if a command succeeds (exit code 0)
    CommandSucceeds {
        /// Command to run
        command: String,
    },

    /// Use Bivvy's internal marker system
    Marker,

    /// All checks must pass
    All {
        /// List of checks that must all pass
        checks: Vec<CompletedCheck>,
    },

    /// Any check passing is sufficient
    Any {
        /// List of checks where at least one must pass
        checks: Vec<CompletedCheck>,
    },
}

/// Prompt configuration for interactive input
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PromptConfig {
    /// Unique key for this prompt (used in interpolation)
    pub key: String,

    /// Question to display
    pub question: String,

    /// Prompt type: select, multiselect, confirm, input
    #[serde(rename = "type")]
    pub prompt_type: PromptType,

    /// Options for select/multiselect
    #[serde(default)]
    pub options: Vec<PromptOption>,

    /// Default value
    pub default: Option<serde_yaml::Value>,
}

/// Type of interactive prompt
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum PromptType {
    Select,
    Multiselect,
    Confirm,
    Input,
}

/// Option for select/multiselect prompts
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PromptOption {
    /// Display label
    pub label: String,
    /// Value to use when selected
    pub value: String,
}

/// Step-specific output configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StepOutputConfig {
    /// Output mode for this step
    pub default: Option<OutputMode>,

    /// Enable logging for this step
    pub logging: Option<bool>,
}

/// Configuration for a named workflow
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct WorkflowConfig {
    /// Human-readable description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Ordered list of step names to execute
    #[serde(default)]
    pub steps: Vec<String>,

    /// Step-specific overrides for this workflow
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub overrides: HashMap<String, StepOverride>,

    /// Workflow-level settings
    #[serde(skip_serializing_if = "Option::is_none")]
    pub settings: Option<WorkflowSettings>,

    /// Workflow-level environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Workflow-level env file
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,
}

/// Per-step overrides within a workflow
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct StepOverride {
    /// Skip prompts, just run
    #[serde(default, skip_serializing_if = "is_false")]
    pub skip_prompt: bool,

    /// Override required flag
    #[serde(skip_serializing_if = "Option::is_none")]
    pub required: Option<bool>,

    /// Override prompt_if_complete flag
    #[serde(skip_serializing_if = "Option::is_none")]
    pub prompt_if_complete: Option<bool>,
}

/// Workflow-level settings overrides
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct WorkflowSettings {
    /// Force non-interactive mode for this workflow
    #[serde(default, skip_serializing_if = "is_false")]
    pub non_interactive: bool,
}

/// Remote template source configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TemplateSource {
    /// URL to template repository or file
    pub url: String,

    /// Priority (lower = higher priority)
    #[serde(default = "default_priority")]
    pub priority: u32,

    /// Network timeout in seconds
    #[serde(default = "default_timeout")]
    pub timeout: u64,

    /// Cache configuration
    pub cache: Option<CacheConfig>,

    /// Authentication configuration
    pub auth: Option<AuthConfig>,
}

fn default_priority() -> u32 {
    100
}

fn default_timeout() -> u64 {
    30
}

/// Cache configuration for remote templates
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CacheConfig {
    /// Time-to-live (e.g., "7d", "24h")
    pub ttl: String,

    /// Cache strategy: etag, git
    #[serde(default)]
    pub strategy: CacheStrategy,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum CacheStrategy {
    #[default]
    Etag,
    Git,
}

/// Authentication for remote template sources
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuthConfig {
    /// Auth type: bearer, header
    #[serde(rename = "type")]
    pub auth_type: AuthType,

    /// Environment variable containing the token
    pub token_env: String,

    /// Custom header name (for header auth type)
    pub header: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum AuthType {
    Bearer,
    Header,
}

/// Config inheritance source
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExtendsConfig {
    /// URL to base config
    pub url: String,
}

/// Secret configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SecretConfig {
    /// Command to fetch the secret
    pub command: String,
}

/// A variable definition: either a static value or a shell-computed value.
///
/// In YAML, static values are plain strings and computed values use
/// `{ command: "..." }` syntax:
///
/// ```yaml
/// vars:
///   app_name: "bivvy"                       # static
///   version:
///     command: "cat VERSION"                 # computed
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum VarDefinition {
    /// Computed from a shell command's stdout (trimmed).
    Computed {
        /// Shell command to run
        command: String,
    },
    /// A static string value.
    Static(String),
}

/// A project-specific requirement definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CustomRequirement {
    /// How to check if this requirement is satisfied
    pub check: CustomRequirementCheck,

    /// Template to use for installation
    #[serde(skip_serializing_if = "Option::is_none")]
    pub install_template: Option<String>,

    /// Human-readable install instructions
    #[serde(skip_serializing_if = "Option::is_none")]
    pub install_hint: Option<String>,
}

/// Check type for a custom requirement.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum CustomRequirementCheck {
    /// Check if a command succeeds (exit code 0)
    CommandSucceeds {
        /// Command to run
        command: String,
    },

    /// Check if a file or directory exists
    FileExists {
        /// Path to check
        path: String,
    },

    /// Check if a service is reachable
    ServiceReachable {
        /// Command to check reachability (e.g., curl health endpoint)
        command: String,
    },
}

/// Configuration for a named environment.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct EnvironmentConfig {
    /// Rules for auto-detecting this environment.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub detect: Vec<EnvironmentDetectRule>,

    /// Default workflow to run in this environment.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_workflow: Option<String>,

    /// Requirements that are assumed to be satisfied in this environment.
    /// These skip gap detection checks when this environment is active.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub provided_requirements: Vec<String>,
}

/// A rule for auto-detecting an environment.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EnvironmentDetectRule {
    /// Environment variable name to check.
    pub env: String,

    /// If set, the variable must equal this value. If absent, just checks presence.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
}

/// Per-environment overrides for a step.
///
/// All fields are `Option` — only specified fields override the base step.
/// The `env` field uses `HashMap<String, Option<String>>`:
/// `Some(val)` = set/override, `None` = remove the key from the base env.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct StepEnvironmentOverride {
    /// Override step title
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,

    /// Override step description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Override step command
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,

    /// Override/remove env vars (None value = remove key)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, Option<String>>,

    /// Override completed check
    #[serde(skip_serializing_if = "Option::is_none")]
    pub completed_check: Option<CompletedCheck>,

    /// Override precondition
    #[serde(skip_serializing_if = "Option::is_none")]
    pub precondition: Option<CompletedCheck>,

    /// Override skippable
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skippable: Option<bool>,

    /// Override allow_failure
    #[serde(skip_serializing_if = "Option::is_none")]
    pub allow_failure: Option<bool>,

    /// Override requires_sudo
    #[serde(skip_serializing_if = "Option::is_none")]
    pub requires_sudo: Option<bool>,

    /// Override sensitive
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sensitive: Option<bool>,

    /// Override before hooks
    #[serde(skip_serializing_if = "Option::is_none")]
    pub before: Option<Vec<String>>,

    /// Override after hooks
    #[serde(skip_serializing_if = "Option::is_none")]
    pub after: Option<Vec<String>>,

    /// Override dependencies
    #[serde(skip_serializing_if = "Option::is_none")]
    pub depends_on: Option<Vec<String>>,

    /// Override requirements
    #[serde(skip_serializing_if = "Option::is_none")]
    pub requires: Option<Vec<String>>,

    /// Override watches
    #[serde(skip_serializing_if = "Option::is_none")]
    pub watches: Option<Vec<String>>,

    /// Override retry count
    #[serde(skip_serializing_if = "Option::is_none")]
    pub retry: Option<u32>,
}

