    RAILS_ENV: development
    DEBUG: "true"
  parallel: true
  max_parallel: 8
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.settings.logging);
        assert_eq!(
            config.settings.log_path,
