    inputs:
      frozen: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["node_deps"];
        assert_eq!(step.template, Some("yarn".to_string()));
    }

    #[test]
    fn parses_step_with_inline_config() {
