          - label: "Normal"
            value: "install"
          - label: "Frozen"
            value: "install --frozen-lockfile"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["interactive"];
        assert_eq!(step.prompts.len(), 1);
        assert_eq!(step.prompts[0].key, "install_mode");
