    }

    #[test]
    fn parses_step_with_hooks() {
        let yaml = r#"
steps:
  database:
    command: "rails db:setup"
    before:
      - echo "Starting..."
    after:
      - echo "Done!"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["database"];
        assert_eq!(step.before.len(), 1);
        assert_eq!(step.after.len(), 1);
    }

