    #[test]
    fn step_defaults_are_correct() {
        let yaml = r#"
steps:
  minimal:
    command: "echo test"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["minimal"];
